use kuno_text::{Error, TensorType};

// These public bytes and F32 bit patterns were generated by compiling the
// SHA256-pinned upstream C dequantizers, independently of Kuno's decoder.
// See fixtures/daslab-b11232/README.md for complete codebook/field coverage.
const DASLAB_ORACLES: [(TensorType, &[u8]); 4] = [
    (
        TensorType::Iq2S,
        include_bytes!("fixtures/daslab-b11232/iq2_s.bin"),
    ),
    (
        TensorType::Iq3S,
        include_bytes!("fixtures/daslab-b11232/iq3_s.bin"),
    ),
    (
        TensorType::Q5K,
        include_bytes!("fixtures/daslab-b11232/q5_K.bin"),
    ),
    (
        TensorType::Q2_0,
        include_bytes!("fixtures/daslab-b11232/q2_0.bin"),
    ),
];

#[test]
fn daslab_scalar_decode_matches_pinned_independent_c_bits_for_every_fixture_lane() {
    for (kind, fixture) in DASLAB_ORACLES {
        let bytes = kind.block_bytes() as usize;
        let elements = kind.block_elements() as usize;
        let record_bytes = bytes + elements * 4;
        assert!(fixture.len().is_multiple_of(record_bytes));
        let mut packed = Vec::new();
        let mut expected = Vec::new();
        for (record, block) in fixture.chunks_exact(record_bytes).enumerate() {
            let mut actual = vec![f32::NAN; elements];
            kind.decode(&block[..bytes], &mut actual).unwrap();
            for (lane, (actual, expected)) in actual
                .iter()
                .zip(block[bytes..].chunks_exact(4))
                .enumerate()
            {
                let bits = u32::from_le_bytes(expected.try_into().unwrap());
                assert_eq!(
                    actual.to_bits(),
                    bits,
                    "{kind:?}, record={record}, lane={lane}"
                );
            }
            packed.extend_from_slice(&block[..bytes]);
            expected.extend_from_slice(&block[bytes..]);
        }
        // Whole rows must also preserve block boundaries and output ordering.
        let mut actual = vec![f32::NAN; expected.len() / 4];
        kind.decode(&packed, &mut actual).unwrap();
        for (actual, expected) in actual.iter().zip(expected.chunks_exact(4)) {
            assert_eq!(
                actual.to_bits(),
                u32::from_le_bytes(expected.try_into().unwrap())
            );
        }
    }
}

#[test]
fn daslab_malformed_rows_fail_before_any_output_write() {
    for (kind, _) in DASLAB_ORACLES {
        let elements = kind.block_elements() as usize;
        let bytes = kind.block_bytes() as usize;
        for packed_length in [0, bytes - 1, bytes + 1, bytes * 2] {
            let mut output = vec![1234.5; elements];
            assert!(matches!(
                kind.decode(&vec![0; packed_length], &mut output),
                Err(Error::InvalidBufferLength)
            ));
            assert_eq!(output, vec![1234.5; elements]);
        }
        for output_length in [0, 1, elements - 1, elements + 1] {
            let mut output = vec![1234.5; output_length];
            assert!(matches!(
                kind.decode(&vec![0; bytes], &mut output),
                Err(Error::InvalidFormat(_))
            ));
            assert_eq!(output, vec![1234.5; output_length]);
        }
        // Quantized geometry at the largest whole row remains exact without
        // allocating a payload or expanding weights into caller storage.
        let whole = u64::MAX - (u64::MAX % kind.block_elements());
        assert_eq!(
            kind.row_bytes(whole).unwrap(),
            whole / kind.block_elements() * kind.block_bytes()
        );
    }
}

#[test]
fn daslab_exact_ids_and_original_block_geometry_are_distinct() {
    for (id, kind, width, bytes) in [
        (22, TensorType::Iq2S, 256, 82),
        (21, TensorType::Iq3S, 256, 110),
        (13, TensorType::Q5K, 256, 176),
        (42, TensorType::Q2_0, 64, 18),
    ] {
        assert_eq!(TensorType::from_gguf_id(id).unwrap(), kind);
        assert_eq!(kind.gguf_id(), id);
        assert_eq!(kind.block_elements(), width);
        assert_eq!(kind.block_bytes(), bytes);
        assert_eq!(kind.row_bytes(width * 10).unwrap(), bytes * 10);
    }
    assert_eq!(TensorType::Q2_0.row_bytes(640).unwrap(), 180);
    assert_ne!(
        TensorType::Q2_0.block_elements(),
        TensorType::Q4K.block_elements()
    );
    assert!(TensorType::Q2_0.row_bytes(32).is_err());
}

#[test]
fn q2_0_fourth_code_is_plus_two_with_consecutive_low_to_high_pairs() {
    let mut block = [0u8; 18];
    block[..2].copy_from_slice(&0x3c00u16.to_le_bytes());
    block[2..].fill(0b11_10_01_00);
    let mut out = [0.; 64];
    TensorType::Q2_0.decode(&block, &mut out).unwrap();
    for values in out.chunks_exact(4) {
        assert_eq!(values, &[-1., 0., 1., 2.]);
    }
}

#[test]
fn independent_c_fixtures_cover_every_grid_and_stored_sign_byte() {
    for (kind, fixture) in DASLAB_ORACLES[..2].iter().copied() {
        let bytes = kind.block_bytes() as usize;
        let stride = bytes + 1024;
        let (ordinary, grids) = if kind == TensorType::Iq2S {
            (32, 1024)
        } else {
            (8, 512)
        };
        let mut seen_grid = vec![false; grids];
        let mut seen_sign = [false; 256];
        let mut seen_scale = [false; 16];
        for record in fixture.chunks_exact(stride).take(ordinary) {
            for group in 0..8 {
                for octet in 0..4 {
                    if kind == TensorType::Iq2S {
                        let index = usize::from(record[2 + group * 4 + octet])
                            | ((usize::from(record[66 + group]) << (8 - 2 * octet)) & 0x300);
                        seen_grid[index] = true;
                        seen_sign[usize::from(record[34 + group * 4 + octet])] = true;
                        seen_scale[usize::from(record[74 + group] & 15)] = true;
                        seen_scale[usize::from(record[74 + group] >> 4)] = true;
                    } else {
                        let first = 2 + group * 8 + octet * 2;
                        let high = usize::from(record[66 + group]);
                        seen_grid[usize::from(record[first]) | ((high << (8 - 2 * octet)) & 256)] =
                            true;
                        seen_grid
                            [usize::from(record[first + 1]) | ((high << (7 - 2 * octet)) & 256)] =
                            true;
                        seen_sign[usize::from(record[74 + group * 4 + octet])] = true;
                        seen_scale
                            [usize::from((record[106 + group / 2] >> (4 * (group % 2))) & 15)] =
                            true;
                    }
                }
            }
        }
        assert!(seen_grid.into_iter().all(|v| v));
        assert!(seen_sign.into_iter().all(|v| v));
        assert!(seen_scale.into_iter().all(|v| v));
    }
}
